"""Build the Luau roundtrip test for Studio's Command Bar."""

from __future__ import annotations

import argparse
from pathlib import Path


PROJECT = Path(__file__).resolve().parents[1]
ROBLOX = PROJECT / "roblox"
DEFAULT_OUTPUT = ROBLOX / "tests" / "roundtrip_command.lua"


def module(name: str, source: Path) -> str:
    return f"local {name} = (function()\n{source.read_text(encoding='utf-8')}\nend)()\n"


def build(suite: str, offset: int, limit: int | None) -> str:
    sections = [
        "-- Generated by scripts/build_roundtrip_command.py. Paste this file into Studio's Command Bar.\n",
        module("Exporter", ROBLOX / "exporter.lua") if suite != "importer" else "",
        module("Importer", ROBLOX / "importer.lua"),
    ]
    if suite in {"importer", "both"}:
        sections += [
            module("importerSummary", ROBLOX / "tests" / "roundtrip.lua"),
            "print(importerSummary)\n",
            'assert(tonumber(importerSummary:match("FAIL (%d+)")) == 0, "importer regression failed")\n',
        ]
    if suite in {"live", "both"}:
        sections += [
            module("runLiveRoundtrip", ROBLOX / "tests" / "live_roundtrip.lua"),
            'local particles = assert(workspace:FindFirstChild("Particles"), "Workspace.Particles is missing")\n',
            'local dataset = assert(particles:FindFirstChild("Dataset"), "Workspace.Particles.Dataset is missing")\n',
            f"local report = runLiveRoundtrip(Exporter, Importer, dataset, {{ offset = {offset}, limit = {limit if limit is not None else 'nil'} }})\n",
            'print(string.format("ROUNDTRIP checked=%d/%d passed=%d failed=%d exported=%d skipped=%d bursts=%d continuous=%d with_EmitCount=%d", report.checked, report.total, report.passed, report.failed, report.exported, report.skipped, report.bursts, report.continuous, report.withEmitCount))\n',
            "for _, failure in ipairs(report.failures) do warn(failure) end\n",
            'assert(report.checked > 0, "no ParticleEmitters were checked")\n',
            'assert(report.failed == 0, "live roundtrip failed")\n',
        ]
    return "".join(sections)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--suite", choices=("live", "importer", "both"), default="live")
    parser.add_argument("--offset", type=int, default=0, help="0-based start within sorted emitters")
    parser.add_argument("--limit", type=int, help="number of live emitters to check")
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    args = parser.parse_args()
    if args.offset < 0 or (args.limit is not None and args.limit < 0):
        parser.error("offset and limit must be nonnegative")
    output = args.output.resolve()
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(build(args.suite, args.offset, args.limit), encoding="utf-8")
    print(f"Wrote {output}; paste its contents into Roblox Studio's Command Bar.")


if __name__ == "__main__":
    main()
